#pragma once
#include "agentflow/connection_binding.hpp"
#include "nlohmann/json.hpp"
namespace agentflow::connection_values {
inline nlohmann::json identity(const ConnectionBindingIdentity& value){return {{"connection_id",value.connection_id},{"profile_revision",value.profile_revision},{"server_id",value.server_id},{"backend_generation",value.backend_generation},{"protocol_version",value.protocol_version},{"kind","local"}};}
inline nlohmann::json bound(const BoundConnectionSession& value){return {{"binding",identity(value.binding)},{"session",{{"id",value.session.id},{"title",value.session.title},{"parent_id",value.session.parent_id}}}};}
inline nlohmann::json bound(const BoundConnectionMessages& value){auto messages=nlohmann::json::array();for(const auto& item:value.page.messages)messages.push_back({{"id","msg_"+std::to_string(item.sequence)},{"seq",item.sequence},{"role",item.role},{"data",nlohmann::json::parse(item.json)}});return {{"binding",identity(value.binding)},{"session_id",value.session_id},{"messages",std::move(messages)},{"has_more",value.page.next_before_sequence.has_value()},{"next_before",value.page.next_before_sequence?nlohmann::json("msg_"+std::to_string(*value.page.next_before_sequence)):nlohmann::json(nullptr)}};}
inline nlohmann::json run_value(const Run& value){nlohmann::json run={{"id",value.id},{"session_id",value.session_id},{"state",to_string(value.state)},{"parent_id",value.parent_id},{"node_id",value.node_id},{"graph_root",value.graph_root}};if(!value.provider_context_json.empty())run["provider_context"]=nlohmann::json::parse(value.provider_context_json);return run;}
inline nlohmann::json bound(const BoundConnectionRun& value){return {{"binding",identity(value.binding)},{"run",run_value(value.run)}};}
inline nlohmann::json bound(const BoundConnectionRunMessages& value){auto result=bound(BoundConnectionMessages{value.binding,value.session_id,value.page});result["run_id"]=value.run_id;return result;}
inline nlohmann::json bound(const BoundConnectionChildHistory& value){auto result=bound(BoundConnectionMessages{value.binding,value.session_id,MessagePage{value.messages,{}}});result.erase("has_more");result.erase("next_before");result["parent_id"]=value.parent_id;result["child_id"]=value.child_id;return result;}
inline nlohmann::json operation(const Operation& value){return {{"id",value.id},{"run_id",value.spec.run_id},{"workspace_id",value.spec.workspace},{"tool",value.spec.tool},{"arguments_json",value.spec.arguments_json},{"resources",value.spec.resources},{"state",to_string(value.state)},{"expires_unix_ms",value.expires_unix_ms},{"decision_actor",value.decision_actor},{"result_json",value.result_json}};}
inline nlohmann::json bound(const BoundConnectionOperation& value){return {{"binding",identity(value.binding)},{"operation",operation(value.operation)}};}
inline nlohmann::json permission_grants(const AgentPermissionGrantSnapshot& value){auto grants=nlohmann::json::array();for(const auto& item:value.grants)grants.push_back({{"id",item.id},{"workspace_id",item.workspace_id},{"policy_binding",item.policy_binding},{"action",item.action},{"resource",item.resource},{"created_unix_ms",item.created_unix_ms}});return {{"revision",value.revision},{"grants",std::move(grants)}};}
inline nlohmann::json permission_requests(const std::string& session,const std::vector<AgentPermissionPendingRequest>& value){auto requests=nlohmann::json::array();for(const auto& item:value){auto encoded=operation(item.operation);if(item.context)encoded["agent_permission_request"]={{"grantable",true},{"action",item.context->action},{"resource",item.context->resource},{"grant_id",item.context->grant_id}};requests.push_back(std::move(encoded));}return {{"session_id",session},{"requests",std::move(requests)}};}
inline nlohmann::json bound(const BoundConnectionPermissionReply& value){return {{"binding",identity(value.binding)},{"session_id",value.session_id},{"operation",operation(value.operation)}};}
inline nlohmann::json bound(const BoundConnectionPermissions& value){auto result=permission_requests(value.session_id,value.requests);result["binding"]=identity(value.binding);return result;}
inline nlohmann::json bound(const BoundConnectionPermissionGrants& value){auto result=permission_grants(value.snapshot);result["session_id"]=value.session_id;result["binding"]=identity(value.binding);return result;}
inline nlohmann::json bound(const BoundConnectionOperations& value){auto operations=nlohmann::json::array();for(const auto& item:value.operations)operations.push_back(operation(item));return {{"binding",identity(value.binding)},{"session_id",value.session_id},{"run_id",value.run_id},{"operations",std::move(operations)}};}
inline nlohmann::json session_model(const std::string& session,const SessionModelState& value){const auto selected=value.selected?nlohmann::json{{"model_id",value.selected->model_id},{"provider_profile_id",value.selected->provider_profile_id},{"provider_route_id",value.selected->provider_route_id}}:nlohmann::json(nullptr);return {{"session_id",session},{"revision",value.revision},{"editable",value.editable},{"selected",selected}};}
inline nlohmann::json bound(const BoundConnectionModel& value){return {{"binding",identity(value.binding)},{"model",session_model(value.session_id,value.state)}};}
inline nlohmann::json command_catalogue(const ConnectionCommandCatalogue& value){auto result=nlohmann::json::parse(value.json);result["workspace_id"]=value.workspace.workspace_id;result["authority_id"]=value.workspace.authority_id;return result;}
inline nlohmann::json bound(const BoundConnectionCommands& value){auto result=command_catalogue(value.catalogue);result["binding"]=identity(value.binding);return result;}
inline nlohmann::json workspace(const ExecutionWorkspaceMetadata& value){return {{"configured",value.configured},{"root",value.configured?nlohmann::json(value.root):nlohmann::json(nullptr)},{"workspace_id",value.configured?nlohmann::json(value.workspace_id):nlohmann::json(nullptr)},{"authority_id",value.configured?nlohmann::json(value.authority_id):nlohmann::json(nullptr)}};}
inline nlohmann::json membership(const WorkspaceMembershipSnapshot& value){auto folders=nlohmann::json::array();for(const auto& folder:value.folders)folders.push_back({{"folder_id",folder.folder_id},{"root",folder.root}});return {{"workspace_id",value.workspace_id},{"revision",value.revision},{"primary_folder_id",value.folders.empty()?std::string{}:value.folders.front().folder_id},{"folders",std::move(folders)}};}
inline nlohmann::json bound(const BoundConnectionWorkspace& value){return {{"binding",identity(value.binding)},{"workspace",workspace(value.workspace)}};}
inline nlohmann::json bound(const BoundConnectionMembership& value){return {{"binding",identity(value.binding)},{"membership",membership(value.membership)}};}
inline nlohmann::json folder_scope(const ConnectionFolderScope& value){return {{"binding",identity(value.binding)},{"workspace_id",value.workspace_id},{"folder_id",value.folder_id},{"revision",value.revision},{"path",value.path}};}
inline nlohmann::json bound(const BoundConnectionFiles& value){auto result=folder_scope(value.scope),entries=nlohmann::json::array();for(const auto& item:value.listing.entries)entries.push_back({{"name",item.name},{"kind",item.kind}});result["entries"]=std::move(entries);result["truncated"]=value.listing.truncated;return result;}
inline nlohmann::json bound(const BoundConnectionFile& value){auto result=folder_scope(value.scope);result["path"]=value.file.path;result["content"]=value.file.content;return result;}
inline nlohmann::json bound(const BoundConnectionFind& value){auto result=folder_scope(value.scope),entries=nlohmann::json::array();for(const auto& item:value.found.entries)entries.push_back({{"path",item.path},{"type",item.type}});result["entries"]=std::move(entries);result["truncated"]=value.found.truncated;result["limits"]=value.found.limits;return result;}
inline nlohmann::json model_catalog(const std::vector<std::string>& models){auto entries=nlohmann::json::array();for(const auto& model:models)entries.push_back({{"id",model}});return {{"default_model",models.empty()?"":models.front()},{"models",std::move(entries)}};}
inline nlohmann::json provider_profiles(const ProviderProfileRuntimeMetadata& value,const std::vector<ProviderProfileRouteMetadata>& policy){
    auto profiles=nlohmann::json::array(),routes=nlohmann::json::array();for(const auto& item:value.profiles)profiles.push_back({{"id",item.id},{"route_id",item.route_id},{"provider",item.provider},{"model",item.model},{"revision",item.revision}});
    for(const auto& item:policy){const char* wire=nullptr;switch(item.wire){case ProviderWire::chat_completions:wire="chat-completions";break;case ProviderWire::responses:wire="responses";break;case ProviderWire::anthropic_messages:wire="anthropic-messages";break;case ProviderWire::gemini_generate_content:wire="gemini-generate-content";break;}if(!wire)throw std::invalid_argument("Unknown backend provider wire");routes.push_back({{"id",item.id},{"provider",item.provider},{"wire",wire},{"discovery",item.discovery}});}
    return {{"revision",value.revision},{"active",value.active},{"profiles",std::move(profiles)},{"routes",std::move(routes)}};
}
inline nlohmann::json bound(const BoundConnectionProviderModels& value){auto models=nlohmann::json::array();for(const auto& id:value.models)models.push_back({{"id",id}});return {{"binding",identity(value.binding)},{"models",std::move(models)}};}
inline nlohmann::json bound(const BoundConnectionProviders& value){return {{"binding",identity(value.binding)},{"providers",provider_profiles(value.configuration,value.routes)}};}
inline nlohmann::json bound(const BoundConnectionModels& value){auto result=model_catalog(value.models);result["binding"]=identity(value.binding);return result;}
inline nlohmann::json cursor(const ConnectionEventCursor& value){return {{"server_id",value.server_id},{"connection_id",value.connection_id},{"session_id",value.session_id},{"run_id",value.run_id},{"sequence",value.sequence}};}
inline ConnectionEventCursor cursor(const nlohmann::json& value){
    if(!value.is_object()||value.size()!=5||!value.contains("sequence")||!value["sequence"].is_number_integer())throw std::invalid_argument("Invalid connection event cursor");
    ConnectionEventCursor result;result.sequence=value["sequence"].get<std::int64_t>();
    for(const auto* key:{"server_id","connection_id","session_id","run_id"})if(!value.contains(key)||!value[key].is_string()||value[key].get_ref<const std::string&>().size()>256)throw std::invalid_argument("Invalid connection event cursor identity");
    result.server_id=value["server_id"];result.connection_id=value["connection_id"];result.session_id=value["session_id"];result.run_id=value["run_id"];return result;
}
inline nlohmann::json page(const ConnectionEventPage& value){auto events=nlohmann::json::array();for(const auto& event:value.events)events.push_back({{"sequence",event.sequence},{"run_id",event.run_id},{"kind",event.kind},{"json",event.json}});return {{"events",std::move(events)},{"cursor",cursor(value.cursor)}};}
inline nlohmann::json graph_record(const GraphRootRecord& root){return {{"run",run_value(root.run)},{"graph_id",root.graph_id},{"graph_revision",root.graph_revision},{"checkpoint_revision",root.checkpoint_revision},{"checkpoint",nlohmann::json::parse(root.checkpoint_json)},{"spec",nlohmann::json::parse(root.specification_json)},{"input",root.input_json.empty()?nlohmann::json(nullptr):nlohmann::json::parse(root.input_json)}};}
inline nlohmann::json graph_snapshot(const ConnectionGraphSnapshot& value){auto result=graph_record(value.record);result["context"]={{"enabled",value.context.enabled},{"resumable",value.context.resumable},{"remaining_active_ms",value.context.remaining_active_ms?nlohmann::json(*value.context.remaining_active_ms):nlohmann::json(nullptr)}};return result;}
inline nlohmann::json bound(const BoundConnectionGraph& value){return {{"binding",identity(value.binding)},{"graph",graph_snapshot(value.graph)}};}
inline nlohmann::json bound(const BoundConnectionGraphUpdate& value){return {{"binding",identity(value.binding)},{"graph",graph_record(value.graph)}};}
inline nlohmann::json bound(const BoundConnectionGraphChildren& value){auto children=nlohmann::json::array();for(const auto& child:value.children)children.push_back(run_value(child));return {{"binding",identity(value.binding)},{"root_id",value.root_id},{"session_id",value.session_id},{"children",std::move(children)}};}
inline nlohmann::json bound(const BoundConnectionGraphs& value){auto entries=nlohmann::json::array();for(const auto& graph:value.graphs)entries.push_back({{"id",graph.id},{"revision",graph.revision},{"node_count",graph.node_count},{"executable",graph.executable}});return {{"binding",identity(value.binding)},{"graphs",std::move(entries)}};}

}
